//! Team logos (31 Oct, user request): `team_logos.json` is generated by
//! `scripts/gen_team_logos.py` from the Brandfetch export in `assets/team-logos/` (repo root),
//! one 96 px PNG per team under `public/teams/`, served at `/teams/...`.
//!
//! A card's team is matched by name: both sides are normalised (lower case, accents folded,
//! club words such as "FC", "CF", "SV" and bare numbers dropped, a few common short forms
//! expanded), then an exact match wins, else one whose words contain the other's (`"Leverkusen"`
//! finds "Bayer 04 Leverkusen"). Teams of the game's own sport are tried first; another sport
//! only matches exactly (EuroLeague's Real Madrid wears the club's crest). No match: `None`, and
//! the screen keeps its code circle or sport icon.

use std::sync::LazyLock;

#[derive(serde::Deserialize)]
struct Entry {
    team: String,
    sport: String,
    path: String,
}

struct Logo {
    words: Vec<String>,
    sport: String,
    path: &'static str,
}

static LOGOS: LazyLock<Vec<Logo>> = LazyLock::new(|| {
    serde_json::from_str::<Vec<Entry>>(include_str!("team_logos.json"))
        .unwrap_or_default()
        .into_iter()
        .map(|e| Logo {
            words: words(&e.team),
            sport: e.sport,
            path: Box::leak(e.path.into_boxed_str()),
        })
        .collect()
});

/// Club words that say nothing about which club it is.
const NOISE: [&str; 22] = [
    "fc", "cf", "afc", "sc", "ud", "cd", "rc", "ca", "sv", "tsg", "bv", "vfb", "vfl", "fsv",
    "club", "de", "del", "balompie", "futbol", "the", "ac", "ssc",
];

/// Short forms on cards → the full words in the export.
const ALIASES: [(&str, &str); 7] = [
    ("ny", "new york"),
    ("la", "los angeles"),
    ("munich", "munchen"),
    ("man", "manchester"),
    ("utd", "united"),
    ("spurs", "tottenham hotspur"),
    ("gladbach", "monchengladbach"),
];

fn fold(c: char) -> char {
    match c {
        'à' | 'á' | 'â' | 'ä' | 'ã' | 'å' => 'a',
        'è' | 'é' | 'ê' | 'ë' => 'e',
        'ì' | 'í' | 'î' | 'ï' => 'i',
        'ò' | 'ó' | 'ô' | 'ö' | 'õ' => 'o',
        'ù' | 'ú' | 'û' | 'ü' => 'u',
        'ñ' => 'n',
        'ç' => 'c',
        _ => c,
    }
}

/// The identifying words of a team name.
fn words(name: &str) -> Vec<String> {
    let folded: String = name
        .to_lowercase()
        .replace('ß', "ss")
        .chars()
        .map(fold)
        .map(|c| if c.is_alphanumeric() { c } else { ' ' })
        .collect();
    let mut out = Vec::new();
    for w in folded.split_whitespace() {
        if NOISE.contains(&w) || w.chars().all(|c| c.is_ascii_digit()) {
            continue;
        }
        match ALIASES.iter().find(|(short, _)| *short == w) {
            Some((_, full)) => out.extend(full.split(' ').map(str::to_string)),
            None => out.push(w.to_string()),
        }
    }
    out
}

/// The logo's URL for a team, if the export has it. `soccer`: the game's sport.
pub fn team_logo(name: &str, soccer: bool) -> Option<&'static str> {
    let want = words(name);
    if want.is_empty() {
        return None;
    }
    let sport = if soccer { "soccer" } else { "basketball" };
    let contains = |a: &[String], b: &[String]| b.iter().all(|w| a.contains(w));
    let same: Vec<&Logo> = LOGOS.iter().filter(|l| l.sport == sport).collect();
    if let Some(l) = same.iter().find(|l| l.words == want) {
        return Some(l.path);
    }
    let near: Vec<&&Logo> = same
        .iter()
        .filter(|l| contains(&l.words, &want) || contains(&want, &l.words))
        .collect();
    if near.len() == 1 {
        return Some(near[0].path);
    }
    LOGOS.iter().find(|l| l.words == want).map(|l| l.path)
}
